package com.osrstranslate;

import lombok.extern.slf4j.Slf4j;

import java.io.File;
import java.io.FileInputStream;
import java.io.InputStream;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;

@Slf4j
final class TranslationRepository {
    private static final String TRANSLATIONS = "translations.json";
    private static final String TRANSLATIONS_SKILLS = "translations_skills.json";
    private static final String TRANSLATIONS_QUESTS = "translations_quests.json";
    private static final String TRANSLATIONS_ITEMS = "translations_items.json";
    private static final String TRANSLATIONS_MENU = "translations_menu.json";
    private static final String TRANSLATIONS_OVERHEAD = "translations_overhead.json";
    private static final String TRANSLATIONS_GAME_MESSAGE = "translations_game_message.json";
    private static final String TRANSLATIONS_WELCOME = "translations_welcome.json";
    private static final String TRANSLATIONS_SETTINGS = "translations_settings.json";

    private volatile File remoteCacheDirectory;

    boolean configureRemoteCacheDirectory(File directory) {
        File previous = remoteCacheDirectory;
        remoteCacheDirectory = directory;
        return previous == null ? directory != null : !previous.equals(directory);
    }

    TranslationState loadState() {
        Map<String, String> translations = loadMap(TRANSLATIONS);
        Map<String, String> translationsSkills = loadMap(TRANSLATIONS_SKILLS);
        Map<String, String> translationsQuests = loadMap(TRANSLATIONS_QUESTS);
        Map<String, String> translationsItems = loadMap(TRANSLATIONS_ITEMS);
        Map<String, String> translationsMenu = loadMap(TRANSLATIONS_MENU);
        Map<String, String> translationsOverhead = loadMap(TRANSLATIONS_OVERHEAD);
        Map<String, String> translationsGameMessage = loadMap(TRANSLATIONS_GAME_MESSAGE);
        Map<String, String> translationsWelcome = loadMap(TRANSLATIONS_WELCOME);
        Map<String, String> translationsSettings = loadMap(TRANSLATIONS_SETTINGS);

        TranslationState state = new TranslationState(
            translations,
            translationsSkills,
            translationsQuests,
            translationsItems,
            translationsMenu,
            translationsOverhead,
            translationsGameMessage,
            translationsWelcome,
            translationsSettings,
            new HashSet<>(translations.values()),
            new HashSet<>(translationsSkills.values()),
            new HashSet<>(translationsQuests.values()),
            new HashSet<>(translationsItems.values()),
            new HashSet<>(translationsMenu.values()),
            new HashSet<>(translationsGameMessage.values()),
            new HashSet<>(translationsWelcome.values()),
            new HashSet<>(translationsSettings.values()),
            TranslationLookupHelper.compileRegexTranslations(translations),
            TranslationLookupHelper.compileRegexTranslations(translationsOverhead),
            TranslationLookupHelper.compileRegexTranslations(translationsGameMessage),
            TranslationLookupHelper.compileRegexTranslations(translationsWelcome),
            buildReverseMenuMap(translationsMenu)
        );

        log.info(
            "PT-BR carregado: dialogos={} skills={} quests={} items={} menu={} "
                + "overhead={} gameMessages={} welcome={} settings={} regex={} "
                + "overheadRegex={} welcomeRegex={}",
            translations.size(),
            translationsSkills.size(),
            translationsQuests.size(),
            translationsItems.size(),
            translationsMenu.size(),
            translationsOverhead.size(),
            translationsGameMessage.size(),
            translationsWelcome.size(),
            translationsSettings.size(),
            state.regexTranslations.size(),
            state.regexOverheadTranslations.size(),
            state.regexWelcomeTranslations.size()
        );
        return state;
    }

    private Map<String, String> loadMap(String fileName) {
        File cacheDirectory = remoteCacheDirectory;
        if (cacheDirectory == null) {
            return Collections.emptyMap();
        }

        File remoteFile = new File(cacheDirectory, fileName);
        if (!remoteFile.isFile()) {
            log.warn("Arquivo ausente no cache remoto: {}", fileName);
            return Collections.emptyMap();
        }

        try (InputStream input = new FileInputStream(remoteFile)) {
            return TranslationLookupHelper.parseJsonMap(input);
        } catch (Exception e) {
            log.warn("Cache remoto invalido para {}", fileName, e);
            return Collections.emptyMap();
        }
    }

    private Map<String, String> buildReverseMenuMap(Map<String, String> source) {
        Map<String, String> reverse = new LinkedHashMap<>();
        for (Map.Entry<String, String> entry : source.entrySet()) {
            String key = stripMenuText(entry.getKey());
            String value = normalizeMenuLookup(entry.getValue());
            if (key.isEmpty() || value.isEmpty()) {
                continue;
            }
            reverse.putIfAbsent(value, key);
        }
        return reverse;
    }

    private String stripMenuText(String text) {
        return text.replaceAll("<[^>]+>", "").trim();
    }

    private String normalizeMenuLookup(String text) {
        return stripMenuText(text).toLowerCase(Locale.ROOT);
    }
}

package com.osrstranslate;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;

final class TranslationState {
    final Map<String, String> translations;
    final Map<String, String> translationsSkills;
    final Map<String, String> translationsQuests;
    final Map<String, String> translationsItems;
    final Map<String, String> translationsMenu;
    final Map<String, String> translationsOverhead;
    final Map<String, String> translationsGameMessage;
    final Map<String, String> translationsWelcome;
    final Map<String, String> translationsSettings;
    final Set<String> translationValues;
    final Set<String> translationSkillsValues;
    final Set<String> translationQuestsValues;
    final Set<String> translationItemsValues;
    final Set<String> translationMenuValues;
    final Set<String> translationGameMessageValues;
    final Set<String> translationWelcomeValues;
    final Set<String> translationSettingsValues;
    final List<TranslationLookupHelper.PatternEntry> regexTranslations;
    final List<TranslationLookupHelper.PatternEntry> regexOverheadTranslations;
    final List<TranslationLookupHelper.PatternEntry> regexGameMessageTranslations;
    final List<TranslationLookupHelper.PatternEntry> regexWelcomeTranslations;
    final Map<String, String> reverseTranslationsMenu;

    TranslationState(
        Map<String, String> translations,
        Map<String, String> translationsSkills,
        Map<String, String> translationsQuests,
        Map<String, String> translationsItems,
        Map<String, String> translationsMenu,
        Map<String, String> translationsOverhead,
        Map<String, String> translationsGameMessage,
        Map<String, String> translationsWelcome,
        Map<String, String> translationsSettings,
        Set<String> translationValues,
        Set<String> translationSkillsValues,
        Set<String> translationQuestsValues,
        Set<String> translationItemsValues,
        Set<String> translationMenuValues,
        Set<String> translationGameMessageValues,
        Set<String> translationWelcomeValues,
        Set<String> translationSettingsValues,
        List<TranslationLookupHelper.PatternEntry> regexTranslations,
        List<TranslationLookupHelper.PatternEntry> regexOverheadTranslations,
        List<TranslationLookupHelper.PatternEntry> regexGameMessageTranslations,
        List<TranslationLookupHelper.PatternEntry> regexWelcomeTranslations,
        Map<String, String> reverseTranslationsMenu
    ) {
        this.translations = translations;
        this.translationsSkills = translationsSkills;
        this.translationsQuests = translationsQuests;
        this.translationsItems = translationsItems;
        this.translationsMenu = translationsMenu;
        this.translationsOverhead = translationsOverhead;
        this.translationsGameMessage = translationsGameMessage;
        this.translationsWelcome = translationsWelcome;
        this.translationsSettings = translationsSettings;
        this.translationValues = translationValues;
        this.translationSkillsValues = translationSkillsValues;
        this.translationQuestsValues = translationQuestsValues;
        this.translationItemsValues = translationItemsValues;
        this.translationMenuValues = translationMenuValues;
        this.translationGameMessageValues = translationGameMessageValues;
        this.translationWelcomeValues = translationWelcomeValues;
        this.translationSettingsValues = translationSettingsValues;
        this.regexTranslations = regexTranslations;
        this.regexOverheadTranslations = regexOverheadTranslations;
        this.regexGameMessageTranslations = regexGameMessageTranslations;
        this.regexWelcomeTranslations = regexWelcomeTranslations;
        this.reverseTranslationsMenu = reverseTranslationsMenu;
    }

    static TranslationState empty() {
        return new TranslationState(
            Collections.emptyMap(),
            Collections.emptyMap(),
            Collections.emptyMap(),
            Collections.emptyMap(),
            Collections.emptyMap(),
            Collections.emptyMap(),
            Collections.emptyMap(),
            Collections.emptyMap(),
            Collections.emptyMap(),
            Collections.emptySet(),
            Collections.emptySet(),
            Collections.emptySet(),
            Collections.emptySet(),
            Collections.emptySet(),
            Collections.emptySet(),
            Collections.emptySet(),
            Collections.emptySet(),
            Collections.emptyList(),
            Collections.emptyList(),
            Collections.emptyList(),
            Collections.emptyList(),
            Collections.emptyMap()
        );
    }
}

package com.osrstranslate;

import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOptionClicked;

final class ExaminePluginBridge
{
    void restoreEnglishOption(MenuOptionClicked event, OsrsTranslatePlugin plugin)
    {
        if (event == null || plugin == null || !plugin.isMenuTranslationEnabled())
        {
            return;
        }

        MenuEntry entry = event.getMenuEntry();
        if (entry == null)
        {
            return;
        }

        String originalOption = entry.getOption();
        String englishOption = plugin.reverseTranslateMenuOption(originalOption);

        if (englishOption == null)
        {
            return;
        }

        // The visible option may be translated, but RuneLite integrations and
        // plugin callbacks consume the canonical English menu option.
        entry.setOption(englishOption);
    }
}

package com.osrstranslate;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.URI;
import java.net.URISyntaxException;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import java.util.stream.Stream;

final class RemoteTranslationService {
    static final String DEFAULT_MANIFEST_URL =
        "https://api.github.com/repos/walterrezende12-tech/"
            + "osrs-translate-translations/contents/manifest.json?ref=main";

    static final List<String> REQUIRED_FILES = Collections.unmodifiableList(Arrays.asList(
        "translations.json",
        "translations_skills.json",
        "translations_quests.json",
        "translations_items.json",
        "translations_menu.json",
        "translations_overhead.json",
        "translations_game_message.json",
        "translations_welcome.json",
        "translations_settings.json"
    ));

    private static final int SUPPORTED_SCHEMA_VERSION = 1;
    private static final int MAX_MANIFEST_BYTES = 1_000_000;
    private static final long MAX_TRANSLATION_BYTES = 64L * 1024L * 1024L;
    private static final Pattern SAFE_NAME = Pattern.compile("[A-Za-z0-9._-]+");
    private static final Pattern SHA_256 = Pattern.compile("[a-fA-F0-9]{64}");
    private final OkHttpClient httpClient;
    private final Gson gson;
    private final File cacheRoot;

    RemoteTranslationService(OkHttpClient httpClient, Gson gson, File cacheRoot) {
        this.httpClient = httpClient;
        this.gson = gson;
        this.cacheRoot = cacheRoot;
    }

    File getActiveDirectory(String language) {
        String safeLanguage;
        try {
            safeLanguage = requireSafeName(language, "idioma");
        } catch (IOException e) {
            return null;
        }

        File languageRoot = new File(cacheRoot, safeLanguage);
        File activeFile = new File(languageRoot, "active.txt");
        if (!activeFile.isFile()) {
            return null;
        }

        try {
            String releaseId = Files.readString(activeFile.toPath(), StandardCharsets.UTF_8).trim();
            if (!SAFE_NAME.matcher(releaseId).matches()) {
                return null;
            }

            File releaseDirectory = new File(new File(languageRoot, "releases"), releaseId);
            return isCompleteRelease(releaseDirectory) ? releaseDirectory : null;
        } catch (IOException e) {
            return null;
        }
    }

    UpdateResult update(String manifestUrl, String language) throws IOException {
        URI manifestUri = requireHttpsUri(manifestUrl, "manifesto");
        RemoteManifest manifest = readManifest(manifestUri);
        validateManifest(manifest);

        String safeLanguage = requireSafeName(language, "idioma");
        LanguageManifest languageManifest = manifest.languages.get(safeLanguage);
        if (languageManifest == null || languageManifest.files == null) {
            throw new IOException("Idioma nao encontrado no manifesto: " + safeLanguage);
        }

        String releaseId = buildReleaseId(manifest.version, languageManifest);
        File languageRoot = new File(cacheRoot, safeLanguage);
        File releasesRoot = new File(languageRoot, "releases");
        File releaseDirectory = new File(releasesRoot, releaseId);
        File previousDirectory = getActiveDirectory(safeLanguage);
        boolean installed = false;

        if (!isValidRelease(releaseDirectory, languageManifest)) {
            deleteDirectory(releaseDirectory.toPath());
            installRelease(manifestUri, languageManifest, releasesRoot, releaseDirectory);
            installed = true;
        }

        activateRelease(languageRoot, releaseId);
        deleteOldReleases(releasesRoot, releaseId);
        boolean changed = installed
            || previousDirectory == null
            || !previousDirectory.equals(releaseDirectory);
        return new UpdateResult(changed, releaseDirectory, manifest.version);
    }

    private RemoteManifest readManifest(URI manifestUri) throws IOException {
        byte[] bytes = downloadBytes(manifestUri, MAX_MANIFEST_BYTES);
        try {
            RemoteManifest manifest = gson.fromJson(
                new String(bytes, StandardCharsets.UTF_8),
                RemoteManifest.class
            );
            if (manifest == null) {
                throw new IOException("Manifesto remoto vazio");
            }
            return manifest;
        } catch (JsonParseException e) {
            throw new IOException("Manifesto remoto invalido", e);
        }
    }

    private void validateManifest(RemoteManifest manifest) throws IOException {
        if (manifest.schemaVersion != SUPPORTED_SCHEMA_VERSION) {
            throw new IOException("Versao de schema nao suportada: " + manifest.schemaVersion);
        }
        if (manifest.version == null || manifest.version.trim().isEmpty()) {
            throw new IOException("Manifesto sem versao");
        }
        if (manifest.languages == null || manifest.languages.isEmpty()) {
            throw new IOException("Manifesto sem idiomas");
        }
    }

    private void installRelease(
        URI manifestUri,
        LanguageManifest languageManifest,
        File releasesRoot,
        File releaseDirectory
    ) throws IOException {
        Files.createDirectories(releasesRoot.toPath());
        Path stagingDirectory = Files.createTempDirectory(releasesRoot.toPath(), ".staging-");
        boolean installed = false;

        try {
            for (String fileName : REQUIRED_FILES) {
                TranslationFile remoteFile = languageManifest.files.get(fileName);
                validateFileEntry(fileName, remoteFile);

                URI fileUri = requireHttpsUri(
                    manifestUri.resolve(remoteFile.url).toString(),
                    fileName
                );
                Path target = stagingDirectory.resolve(fileName);
                downloadAndValidate(fileUri, target, remoteFile.sha256);
            }

            Files.writeString(stagingDirectory.resolve(".complete"), "ok\n", StandardCharsets.UTF_8);
            moveDirectory(stagingDirectory, releaseDirectory.toPath());
            installed = true;
        } finally {
            if (!installed) {
                try {
                    deleteDirectory(stagingDirectory);
                } catch (IOException ignored) {
                    // Preserve the original download or validation failure.
                }
            }
        }
    }

    private void validateFileEntry(String fileName, TranslationFile remoteFile) throws IOException {
        if (remoteFile == null || remoteFile.url == null || remoteFile.url.trim().isEmpty()) {
            throw new IOException("URL ausente para " + fileName);
        }
        if (remoteFile.sha256 == null || !SHA_256.matcher(remoteFile.sha256).matches()) {
            throw new IOException("SHA-256 invalido para " + fileName);
        }
    }

    private void downloadAndValidate(URI uri, Path target, String expectedSha256) throws IOException {
        MessageDigest digest = sha256Digest();
        Request request = request(uri);

        try (Response response = httpClient.newCall(request).execute()) {
            ResponseBody body = requireSuccessfulBody(response, uri, MAX_TRANSLATION_BYTES);
            long total = 0;

            try (InputStream input = body.byteStream();
                 OutputStream output = Files.newOutputStream(target)) {
                byte[] buffer = new byte[16 * 1024];
                int read;
                while ((read = input.read(buffer)) != -1) {
                    total += read;
                    if (total > MAX_TRANSLATION_BYTES) {
                        throw new IOException("Arquivo remoto excede o limite: " + uri);
                    }
                    digest.update(buffer, 0, read);
                    output.write(buffer, 0, read);
                }
            }
        }

        String actualSha256 = toHex(digest.digest());
        if (!actualSha256.equals(expectedSha256.toLowerCase(Locale.ROOT))) {
            throw new IOException("SHA-256 divergente para " + target.getFileName());
        }

        try (InputStream input = new FileInputStream(target.toFile())) {
            TranslationLookupHelper.parseJsonMapStrict(input);
        } catch (Exception e) {
            throw new IOException("JSON de traducao invalido: " + target.getFileName(), e);
        }
    }

    private byte[] downloadBytes(URI uri, int maximumBytes) throws IOException {
        Request request = request(uri);
        try (Response response = httpClient.newCall(request).execute()) {
            ResponseBody body = requireSuccessfulBody(response, uri, maximumBytes);
            try (InputStream input = body.byteStream();
                 ByteArrayOutputStream output = new ByteArrayOutputStream()) {
                byte[] buffer = new byte[8 * 1024];
                int total = 0;
                int read;
                while ((read = input.read(buffer)) != -1) {
                    total += read;
                    if (total > maximumBytes) {
                        throw new IOException("Resposta remota excede o limite: " + uri);
                    }
                    output.write(buffer, 0, read);
                }
                return output.toByteArray();
            }
        }
    }

    private Request request(URI uri) {
        return new Request.Builder()
            .get()
            .header("Accept", "application/vnd.github.raw+json, application/json")
            .header("User-Agent", "OSRS-Translate-PT-BR/1.0")
            .url(uri.toString())
            .build();
    }

    private ResponseBody requireSuccessfulBody(Response response, URI uri, long maximumBytes)
        throws IOException {
        if (!response.isSuccessful()) {
            throw new IOException("HTTP " + response.code() + " ao baixar " + uri);
        }
        if (!response.request().url().isHttps()) {
            throw new IOException("Redirecionamento para URL nao segura: " + response.request().url());
        }

        ResponseBody body = response.body();
        if (body == null) {
            throw new IOException("Resposta remota vazia: " + uri);
        }
        if (body.contentLength() > maximumBytes) {
            throw new IOException("Resposta remota excede o limite: " + uri);
        }
        return body;
    }

    private void activateRelease(File languageRoot, String releaseId) throws IOException {
        Files.createDirectories(languageRoot.toPath());
        Path temporary = Files.createTempFile(languageRoot.toPath(), "active-", ".tmp");
        try {
            Files.writeString(temporary, releaseId + "\n", StandardCharsets.UTF_8);
            moveFile(temporary, new File(languageRoot, "active.txt").toPath());
        } finally {
            Files.deleteIfExists(temporary);
        }
    }

    private boolean isCompleteRelease(File directory) {
        if (!new File(directory, ".complete").isFile()) {
            return false;
        }
        for (String fileName : REQUIRED_FILES) {
            if (!new File(directory, fileName).isFile()) {
                return false;
            }
        }
        return true;
    }

    private boolean isValidRelease(File directory, LanguageManifest languageManifest) {
        if (!isCompleteRelease(directory)) {
            return false;
        }

        try {
            for (String fileName : REQUIRED_FILES) {
                TranslationFile remoteFile = languageManifest.files.get(fileName);
                validateFileEntry(fileName, remoteFile);
                if (!sha256(new File(directory, fileName))
                    .equals(remoteFile.sha256.toLowerCase(Locale.ROOT))) {
                    return false;
                }
            }
            return true;
        } catch (IOException e) {
            return false;
        }
    }

    private String buildReleaseId(String version, LanguageManifest languageManifest)
        throws IOException {
        MessageDigest digest = sha256Digest();
        for (String fileName : REQUIRED_FILES) {
            TranslationFile remoteFile = languageManifest.files.get(fileName);
            validateFileEntry(fileName, remoteFile);
            digest.update(fileName.getBytes(StandardCharsets.UTF_8));
            digest.update(remoteFile.sha256.toLowerCase(Locale.ROOT).getBytes(StandardCharsets.UTF_8));
        }

        String safeVersion = version.replaceAll("[^A-Za-z0-9._-]", "_");
        if (safeVersion.isEmpty()) {
            safeVersion = "release";
        }
        return safeVersion + "-" + toHex(digest.digest()).substring(0, 12);
    }

    private URI requireHttpsUri(String value, String label) throws IOException {
        try {
            URI uri = new URI(value == null ? "" : value.trim());
            if (!uri.isAbsolute() || !"https".equalsIgnoreCase(uri.getScheme())) {
                throw new IOException("Apenas URL HTTPS e permitida para " + label);
            }
            return uri;
        } catch (URISyntaxException e) {
            throw new IOException("URL invalida para " + label, e);
        }
    }

    private String requireSafeName(String value, String label) throws IOException {
        if (value == null || !SAFE_NAME.matcher(value.trim()).matches()) {
            throw new IOException(label + " invalido");
        }
        return value.trim();
    }

    private MessageDigest sha256Digest() {
        try {
            return MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 indisponivel", e);
        }
    }

    private String toHex(byte[] bytes) {
        StringBuilder result = new StringBuilder(bytes.length * 2);
        for (byte value : bytes) {
            result.append(String.format("%02x", value & 0xff));
        }
        return result.toString();
    }

    private String sha256(File file) throws IOException {
        MessageDigest digest = sha256Digest();
        try (InputStream input = new FileInputStream(file)) {
            byte[] buffer = new byte[16 * 1024];
            int read;
            while ((read = input.read(buffer)) != -1) {
                digest.update(buffer, 0, read);
            }
        }
        return toHex(digest.digest());
    }

    private void moveDirectory(Path source, Path target) throws IOException {
        if (Files.exists(target)) {
            deleteDirectory(source);
            return;
        }
        try {
            Files.move(source, target, StandardCopyOption.ATOMIC_MOVE);
        } catch (AtomicMoveNotSupportedException e) {
            Files.move(source, target);
        }
    }

    private void moveFile(Path source, Path target) throws IOException {
        try {
            Files.move(
                source,
                target,
                StandardCopyOption.ATOMIC_MOVE,
                StandardCopyOption.REPLACE_EXISTING
            );
        } catch (AtomicMoveNotSupportedException e) {
            Files.move(source, target, StandardCopyOption.REPLACE_EXISTING);
        }
    }

    private void deleteDirectory(Path directory) throws IOException {
        if (!Files.exists(directory)) {
            return;
        }
        try (Stream<Path> paths = Files.walk(directory)) {
            List<Path> orderedPaths = paths
                .sorted(Comparator.reverseOrder())
                .collect(Collectors.toList());
            for (Path path : orderedPaths) {
                Files.deleteIfExists(path);
            }
        }
    }

    private void deleteOldReleases(File releasesRoot, String activeReleaseId) {
        File[] releases = releasesRoot.listFiles(File::isDirectory);
        if (releases == null) {
            return;
        }
        for (File release : releases) {
            if (!release.getName().equals(activeReleaseId)
                && !release.getName().startsWith(".staging-")) {
                try {
                    deleteDirectory(release.toPath());
                } catch (IOException ignored) {
                    // Old cache cleanup must not invalidate an activated release.
                }
            }
        }
    }

    static final class UpdateResult {
        private final boolean changed;
        private final File activeDirectory;
        private final String version;

        private UpdateResult(boolean changed, File activeDirectory, String version) {
            this.changed = changed;
            this.activeDirectory = activeDirectory;
            this.version = version;
        }

        boolean isChanged() {
            return changed;
        }

        File getActiveDirectory() {
            return activeDirectory;
        }

        String getVersion() {
            return version;
        }
    }

    private static final class RemoteManifest {
        private int schemaVersion;
        private String version;
        private Map<String, LanguageManifest> languages;
    }

    private static final class LanguageManifest {
        private Map<String, TranslationFile> files;
    }

    private static final class TranslationFile {
        private String url;
        private String sha256;
    }
}

package com.osrstranslate;

import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class WelcomeTranslationService {
    private static final int WELCOME_SCREEN = 378;
    private static final String LAST_LOGIN_TEMPLATE = "You last logged in [value] ago.";
    private static final String HANS_TEMPLATE_KEY = "__hans.template";
    private static final Pattern WELCOME_LAST_LOGIN_PATTERN =
        Pattern.compile("^You last logged in (.+) ago\\.$");
    private static final Pattern ENGLISH_DURATION_UNIT_PATTERN =
        Pattern.compile("\\b(\\d[\\d,]*)\\s+(day|days|hour|hours|minute|minutes|second|seconds)\\b");
    private static final Pattern ENGLISH_SINGLE_DURATION_UNIT_PATTERN =
        Pattern.compile("\\b(a|an)\\s+(day|hour|minute|second)\\b");
    private static final Pattern HANS_PATTERN = Pattern.compile(
        "^You've spent (\\d[\\d,]*) (day|days), (\\d[\\d,]*) (hour|hours), "
            + "(\\d[\\d,]*) (minute|minutes) in the world since you arrived "
            + "(\\d[\\d,]*) (day|days) ago\\.$"
    );
    private static final Pattern NUMBER_PATTERN = Pattern.compile("(\\d[\\d,]*)");

    String translateSpecialText(
        String lookup,
        int interfaceId,
        Set<Integer> loginInterfaceGroups,
        Map<String, String> translations
    ) {
        if (isHansTimePlayedMessage(lookup)) {
            return translateHans(lookup, translations);
        }

        if (interfaceId != WELCOME_SCREEN && !loginInterfaceGroups.contains(interfaceId)) {
            return null;
        }

        Matcher matcher = WELCOME_LAST_LOGIN_PATTERN.matcher(lookup);
        if (!matcher.matches()) {
            return null;
        }

        String template = translations.get(LAST_LOGIN_TEMPLATE);
        if (template == null || template.isEmpty()) {
            return null;
        }

        return template.replace("[value]", translateEnglishDuration(matcher.group(1), translations));
    }

    private boolean isHansTimePlayedMessage(String lookup) {
        return lookup.startsWith("You've spent")
            && lookup.contains("in the world since you arrived")
            && lookup.endsWith("ago.");
    }

    private String translateHans(String clean, Map<String, String> translations) {
        String template = translations.get(HANS_TEMPLATE_KEY);
        if (template == null || template.isEmpty()) {
            return null;
        }

        Matcher matcher = HANS_PATTERN.matcher(clean);
        String daysInWorld;
        String daysInWorldUnit;
        String hoursInWorld;
        String hoursInWorldUnit;
        String minutesInWorld;
        String minutesInWorldUnit;
        String daysSinceArrival;
        String daysSinceArrivalUnit;
        if (matcher.matches()) {
            daysInWorld = matcher.group(1);
            daysInWorldUnit = translateDurationUnit(matcher.group(2), translations);
            hoursInWorld = matcher.group(3);
            hoursInWorldUnit = translateDurationUnit(matcher.group(4), translations);
            minutesInWorld = matcher.group(5);
            minutesInWorldUnit = translateDurationUnit(matcher.group(6), translations);
            daysSinceArrival = matcher.group(7);
            daysSinceArrivalUnit = translateDurationUnit(matcher.group(8), translations);
        } else {
            Matcher fallback = NUMBER_PATTERN.matcher(clean);
            daysInWorld = findNext(fallback);
            hoursInWorld = findNext(fallback);
            minutesInWorld = findNext(fallback);
            daysSinceArrival = findNext(fallback);
            daysInWorldUnit = translateDurationUnit("days", translations);
            hoursInWorldUnit = translateDurationUnit("hours", translations);
            minutesInWorldUnit = translateDurationUnit("minutes", translations);
            daysSinceArrivalUnit = translateDurationUnit("days", translations);
        }

        return template
            .replace("[daysInWorld]", daysInWorld)
            .replace("[daysUnit]", daysInWorldUnit)
            .replace("[hoursInWorld]", hoursInWorld)
            .replace("[hoursUnit]", hoursInWorldUnit)
            .replace("[minutesInWorld]", minutesInWorld)
            .replace("[minutesUnit]", minutesInWorldUnit)
            .replace("[daysSinceArrival]", daysSinceArrival)
            .replace("[daysSinceArrivalUnit]", daysSinceArrivalUnit);
    }

    private String findNext(Matcher matcher) {
        return matcher.find() ? matcher.group(1) : "";
    }

    private String translateEnglishDuration(String text, Map<String, String> translations) {
        Matcher matcher = ENGLISH_DURATION_UNIT_PATTERN.matcher(text);
        StringBuffer translated = new StringBuffer();
        boolean found = false;

        while (matcher.find()) {
            found = true;
            String amount = matcher.group(1);
            String unit = matcher.group(2);
            matcher.appendReplacement(
                translated,
                Matcher.quoteReplacement(amount + " " + translateDurationUnit(unit, translations))
            );
        }

        if (!found) {
            Matcher singleMatcher = ENGLISH_SINGLE_DURATION_UNIT_PATTERN.matcher(text);
            StringBuffer singleTranslated = new StringBuffer();
            boolean singleFound = false;

            while (singleMatcher.find()) {
                singleFound = true;
                String unit = singleMatcher.group(2);
                singleMatcher.appendReplacement(
                    singleTranslated,
                    Matcher.quoteReplacement("1 " + translateDurationUnit(unit, translations))
                );
            }

            if (!singleFound) {
                return text;
            }

            singleMatcher.appendTail(singleTranslated);
            return singleTranslated.toString();
        }

        matcher.appendTail(translated);
        return translated.toString();
    }

    private String translateDurationUnit(String unit, Map<String, String> translations) {
        String translated = translations.get("__duration." + unit);
        return translated == null || translated.isEmpty() ? unit : translated;
    }
}

